-- Initial schema. All primary keys are UUIDv7, generated by PostgreSQL 18's
-- native uuidv7() by default — inserts never need to supply an id. The
-- backend may still pre-generate one with `Uuid::now_v7()` when it wants the
-- id before the INSERT; both produce time-ordered v7 values.

CREATE TYPE section AS ENUM ('blog', 'project', 'library', 'experience');

-- Keeps `updated_at` honest on every UPDATE, so application code never has
-- to remember to set it.
CREATE FUNCTION set_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$;

-- One table for all published content; `section` filters the pages.
CREATE TABLE entries (
    id          uuid PRIMARY KEY DEFAULT uuidv7(),
    section     section     NOT NULL,
    slug        text        NOT NULL,
    title       text        NOT NULL,
    source_link text,
    cover_image text,
    category    text,
    body        text        NOT NULL,
    -- Section-specific odds and ends (experience period, project subtitle,
    -- library author/reading status, blog reading-time) — display data that
    -- does not warrant its own column.
    extra       jsonb       NOT NULL DEFAULT '{}'::jsonb,
    draft       boolean     NOT NULL DEFAULT true,
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now(),
    UNIQUE (section, slug)
);

CREATE INDEX entries_section_published_idx
    ON entries (section, created_at DESC)
    WHERE NOT draft;

CREATE TRIGGER entries_set_updated_at
    BEFORE UPDATE ON entries
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Tags are normalized: one row per distinct tag, joined to entries through
-- entry_tags. No duplicated text, and filtering/counting by tag is a join.
CREATE TABLE tags (
    id   uuid PRIMARY KEY DEFAULT uuidv7(),
    name text NOT NULL UNIQUE          -- stored lowercased; display-case in UI
);

CREATE TABLE entry_tags (
    entry_id uuid NOT NULL REFERENCES entries (id) ON DELETE CASCADE,
    tag_id   uuid NOT NULL REFERENCES tags (id) ON DELETE CASCADE,
    PRIMARY KEY (entry_id, tag_id)
);

-- Covers the reverse lookup: "all entries with tag X".
CREATE INDEX entry_tags_tag_idx ON entry_tags (tag_id, entry_id);

-- One account per person, created on the first verified comment.
-- `email` is the lowercased address as entered (codes are sent to it);
-- `normalized_email` collapses aliasing (`user+tag@` → `user@`, and dot/
-- googlemail variants for Gmail) and carries the UNIQUE constraint, so
-- user@ and user+1@ can never become two accounts.
CREATE TABLE commenters (
    id               uuid PRIMARY KEY DEFAULT uuidv7(),
    email            text        NOT NULL CHECK (email = lower(email)),
    normalized_email text        NOT NULL UNIQUE
        CHECK (normalized_email = lower(normalized_email)),
    name             text,
    created_at       timestamptz NOT NULL DEFAULT now(),
    last_seen_at     timestamptz NOT NULL DEFAULT now()
);

-- One-time email verification codes. Only a hash of the code is stored;
-- a row is either consumed on success or dies at `expires_at`.
CREATE TABLE email_verifications (
    id          uuid PRIMARY KEY DEFAULT uuidv7(),
    email       text        NOT NULL,
    code_hash   text        NOT NULL,
    attempts    smallint    NOT NULL DEFAULT 0,
    expires_at  timestamptz NOT NULL,
    consumed_at timestamptz,
    created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX email_verifications_email_idx
    ON email_verifications (email, created_at DESC);

-- Blog comments. Flattened Instagram-style threading: one level via
-- `parent_id`, with `replying_to` naming who the reply @tags.
CREATE TABLE comments (
    id           uuid PRIMARY KEY DEFAULT uuidv7(),
    entry_id     uuid        NOT NULL REFERENCES entries (id) ON DELETE CASCADE,
    commenter_id uuid        NOT NULL REFERENCES commenters (id) ON DELETE CASCADE,
    parent_id    uuid        REFERENCES comments (id) ON DELETE CASCADE,
    replying_to  text,
    body         text        NOT NULL,
    read         boolean     NOT NULL DEFAULT false,
    created_at   timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX comments_entry_idx ON comments (entry_id, created_at);
CREATE INDEX comments_unread_idx ON comments (created_at DESC) WHERE NOT read;

-- Contact-form emails. Nothing else is recorded here.
CREATE TABLE messages (
    id           uuid PRIMARY KEY DEFAULT uuidv7(),
    sender_name  text        NOT NULL,
    sender_email text        NOT NULL,
    body         text        NOT NULL,
    read         boolean     NOT NULL DEFAULT false,
    created_at   timestamptz NOT NULL DEFAULT now()
);

-- The site's operators. Deliberately separate from commenters: there is no
-- signup path of any kind — rows are inserted only through direct database
-- access. The email address is the sign-in identity.
CREATE TABLE users (
    id            uuid PRIMARY KEY DEFAULT uuidv7(),
    email         text        NOT NULL UNIQUE CHECK (email = lower(email)),
    password_hash text        NOT NULL,      -- argon2, via password-auth
    totp_secret   text,                      -- NULL until MFA is enrolled
    created_at    timestamptz NOT NULL DEFAULT now(),
    last_login_at timestamptz
);

-- Admin sessions: a random token lives in the cookie, only its SHA-256 hash
-- is stored. Rows die at expires_at; logout deletes them eagerly.
CREATE TABLE sessions (
    id           uuid PRIMARY KEY DEFAULT uuidv7(),
    user_id      uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    token_hash   text        NOT NULL UNIQUE,
    ip           text,
    user_agent   text,
    expires_at   timestamptz NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    last_seen_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX sessions_expiry_idx ON sessions (expires_at);

-- WebAuthn passkeys; `credential` is the serialized webauthn-rs Passkey.
CREATE TABLE user_passkeys (
    id           uuid PRIMARY KEY DEFAULT uuidv7(),
    user_id      uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    label        text,
    credential   jsonb       NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    last_used_at timestamptz
);

-- Server state for an in-flight WebAuthn ceremony; claimed rows are deleted.
CREATE TABLE webauthn_challenges (
    id         uuid PRIMARY KEY DEFAULT uuidv7(),
    user_id    uuid REFERENCES users (id) ON DELETE CASCADE,
    state      jsonb       NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL
);

CREATE INDEX webauthn_challenges_expires_at_idx ON webauthn_challenges (expires_at);

-- Uploaded files (images, videos, the CV). The bytes live on disk in the
-- media volume; `path` is the file's location relative to the volume root
-- (conventionally `<id>.<ext>`). This table is the ledger that lets the
-- admin list media and sweep orphans.
CREATE TABLE media (
    id            uuid PRIMARY KEY DEFAULT uuidv7(),
    path          text        NOT NULL UNIQUE,
    mime          text        NOT NULL,
    bytes         bigint      NOT NULL,
    alt_text      text,
    original_name text,
    created_at    timestamptz NOT NULL DEFAULT now()
);

-- Robot chatter and 404 quips, editable at admin → Quips.
CREATE TYPE quip_kind AS ENUM ('chatter', 'not_found');

CREATE TABLE quips (
    id         uuid PRIMARY KEY DEFAULT uuidv7(),
    kind       quip_kind   NOT NULL,
    body       text        NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX quips_kind_idx ON quips (kind);

-- Singleton content that does not fit the entries model: the profile, the
-- now page (status readout, building, toolbox), home metrics. One row per
-- well-known key, shaped as JSON.
CREATE TABLE site_content (
    key        text PRIMARY KEY,
    value      jsonb       NOT NULL,
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TRIGGER site_content_set_updated_at
    BEFORE UPDATE ON site_content
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Anonymous, first-party view counters (per entry, per day) — what the
-- cookie banner promises powers the post view counts. No visitor identity
-- is ever stored.
CREATE TABLE page_views (
    entry_id uuid   NOT NULL REFERENCES entries (id) ON DELETE CASCADE,
    day      date   NOT NULL,
    views    bigint NOT NULL DEFAULT 0,
    PRIMARY KEY (entry_id, day)
);
